def cube(extra=None, hl=None):
    ed = [['A', 'B'], ['B', 'C'], ['C', 'D'], ['D', 'A'], ['A′', 'B′'], ['B′', 'C′'], ['C′', 'D′'], ['D′', 'A′'], ['A', 'A′'], ['B', 'B′'], ['C', 'C′'], ['D', 'D′']]
